using System;
using System.Buffers.Binary;

namespace Assimalign.Cohesion.Content.Bmff.Tests;

// Hand-authored ISO/IEC 14496-12 field vectors; never generated by the reader under test.
internal static class BmffMalformedFixtures
{
    internal static byte[] Words(params uint[] values)
    {
        var bytes = new byte[values.Length * 4];
        for (var i = 0; i < values.Length; i++)
        {
            BinaryPrimitives.WriteUInt32BigEndian(bytes.AsSpan(i * 4), values[i]);
        }
        return bytes;
    }

    internal static byte[] MissingEntries(string type) => BmffFixtures.Box(type, type switch
    {
        "stts" or "ctts" or "stss" or "stsc" or "stco" or "co64" or "subs" or "dref" or "stsd" => Words(0, 1),
        "elst" => Words(0x01000000, 1),
        "stsz" => Words(0, 0, 1),
        "stz2" => Words(0, 4, 1),
        "trun" => Words(0x100, 1),
        "sbgp" => Words(0, 0x726f6c6c, 1),
        "sgpd" => Words(0x01000000, 0x726f6c6c, 2, 1),
        "tfra" => Words(0, 1, 0, 1),
        "iloc" => Words(0, 0x44000001),
        "iinf" => [0, 0, 0, 0, 0, 1],
        _ => throw new ArgumentException(nameof(type))
    });
}
